begin;
set local lock_timeout='5s';set local statement_timeout='30s';

do $preflight$
begin
 if not exists(select 1 from pg_proc where oid=to_regprocedure('private.player_need_salary_check(uuid,uuid,uuid)') and md5(prosrc)='a3a298d8f86b038c7c31c359797bdc9e' and not prosecdef and proconfig=array['search_path=""']) then raise exception 'Unreviewed salary comparison dependency';end if;
 if not exists(select 1 from pg_proc where oid=to_regprocedure('public.platform_server_career_pursuit_gate(uuid,uuid)') and md5(prosrc)='2088a069c07de181aeeaf925ffed8c00' and prosecdef and proconfig=array['search_path=""']) then raise exception 'Unreviewed career-control dependency';end if;
 if has_table_privilege('authenticated','platform.audit_events','INSERT') or has_table_privilege('authenticated','platform.audit_events','UPDATE') or has_table_privilege('authenticated','platform.audit_events','DELETE') or has_table_privilege('anon','platform.audit_events','INSERT') then raise exception 'Financial approval audit authority is not private';end if;
end $preflight$;

-- Lock canonical context in request -> player -> facts -> match order. The
-- existing salary writer locks player/facts in that order too. Audit is private;
-- ordinary staff's editable match reasoning is never approval authority.
create function private.lock_pursuit_salary_context(p_tenant_id uuid,p_match_id uuid)
returns djm_os.player_matches language plpgsql security invoker set search_path='' as $lock$
declare m djm_os.player_matches%rowtype;current_match djm_os.player_matches%rowtype;
begin
 select * into m from djm_os.player_matches where id=p_match_id and tenant_id=p_tenant_id;
 if not found then raise exception 'This player opportunity is unavailable' using errcode='42501';end if;
 perform 1 from djm_os.club_needs where id=m.club_need_id and tenant_id=p_tenant_id for update;
 if not found then raise exception 'This club request is unavailable' using errcode='42501';end if;
 perform 1 from public.players where id=m.player_id and tenant_id=p_tenant_id and archived_at is null for update;
 if not found then raise exception 'This player is unavailable' using errcode='42501';end if;
 perform 1 from djm_os.player_market_facts where player_id=m.player_id for update;
 select * into current_match from djm_os.player_matches where id=p_match_id and tenant_id=p_tenant_id for update;
 if not found or current_match.player_id is distinct from m.player_id or current_match.club_need_id is distinct from m.club_need_id then raise exception 'The opportunity changed. Load its current details.' using errcode='40001';end if;
 return current_match;
end $lock$;
revoke all on function private.lock_pursuit_salary_context(uuid,uuid) from public,anon,authenticated,service_role;

create function private.pursuit_salary_gate(p_tenant_id uuid,p_match_id uuid)
returns jsonb language plpgsql stable security invoker set search_path='' as $gate$
declare m djm_os.player_matches%rowtype;n djm_os.club_needs%rowtype;a platform.audit_events%rowtype;comparison jsonb;review jsonb;
 today date:=(now() at time zone 'UTC')::date;same_context boolean:=false;current_review boolean:=false;override_active boolean:=false;proceed boolean:=false;state text;message text;
begin
 select * into m from djm_os.player_matches where id=p_match_id and tenant_id=p_tenant_id;
 if not found then raise exception 'This player opportunity is unavailable' using errcode='42501';end if;
 select * into n from djm_os.club_needs where id=m.club_need_id and tenant_id=p_tenant_id;
 if not found then raise exception 'This club request is unavailable' using errcode='42501';end if;
 comparison:=private.player_need_salary_check(p_tenant_id,n.id,m.player_id);
 select * into a from platform.audit_events where tenant_id=p_tenant_id and entity_type='player_match' and entity_id=p_match_id::text and action='agency.pursuit_salary_review' order by occurred_at desc,id desc limit 1;
 same_context:=a.id is not null and a.after_state#>>'{context,player_id}'=m.player_id::text and a.after_state#>>'{context,club_need_id}'=n.id::text and a.after_state#>>'{context,club_id}'=n.organisation_id::text;
 current_review:=same_context and a.after_state->>'version'='1' and a.after_state->>'fingerprint'=comparison->>'fingerprint';
 override_active:=current_review and private.user_is_tenant_admin(p_tenant_id,a.actor_user_id) is not distinct from true and a.after_state->>'decision'='explore' and (a.after_state->>'expires_on')::date>=today;
 if n.archived_at is not null or n.status not in('active','open','confirmed') or n.expires_at<now()
  or not exists(select 1 from djm_os.organisations o where o.id=n.organisation_id and o.tenant_id=p_tenant_id and o.archived_at is null) then
  state:='hold_request_unavailable';message:='Review this club request before preparing new external activity.';
 elsif same_context and a.after_state->>'decision'='hold' then
  state:='hold_recorded_review';message:='An agency administrator has kept this salary check on hold.';
 elsif override_active then
  proceed:=true;state:='open_exploration_review';message:='Exploration is permitted under the recorded temporary review. The salary gap or uncertainty remains.';
 elsif comparison->>'state' in('minimum_within_budget','target_within_budget') and comparison->>'needs_source_confirmation'='false' then
  proceed:=true;state:='open_recorded_salary';message:='The confirmed recorded base-salary expectation fits this budget. Contract terms still require agreement.';
 elsif comparison->>'hard_conflict'='true' then
  state:='hold_salary_conflict';message:='The confirmed minimum exceeds the budget. Resolve the terms or record a justified temporary exploration decision.';
 else
  state:='review_salary_evidence';message:='Resolve the missing or incompatible salary evidence, or record why this route should be explored before it is resolved.';
 end if;
 if a.id is not null then review:=jsonb_build_object('id',a.id,'decision',a.after_state->>'decision','reason',a.after_state->>'reason','expires_on',a.after_state->>'expires_on','recorded_at',a.occurred_at,'actor_id',a.actor_user_id,'context',a.after_state->'context','same_context',same_context,'current',current_review,'actor_active',private.user_is_tenant_admin(p_tenant_id,a.actor_user_id),'active',override_active);end if;
 return jsonb_build_object('version',1,'player_match_id',p_match_id,'player_id',m.player_id,'club_need_id',n.id,'club_id',n.organisation_id,'comparison',comparison,'state',state,'message',message,'can_proceed',proceed,'review',review,'expiry_basis','end_of_utc_date');
end $gate$;
revoke all on function private.pursuit_salary_gate(uuid,uuid) from public,anon,authenticated,service_role;

create function public.platform_server_pursuit_salary_review(p_tenant_id uuid,p_actor_user_id uuid,p_match_id uuid,p_command_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $read$
declare result jsonb;receipt uuid;
begin
 if private.user_is_tenant_admin(p_tenant_id,p_actor_user_id) is distinct from true then raise exception 'Agency administrator access required' using errcode='42501';end if;
 result:=private.pursuit_salary_gate(p_tenant_id,p_match_id);
 if p_command_id is not null then select id into receipt from platform.audit_events where id=p_command_id and tenant_id=p_tenant_id and actor_user_id=p_actor_user_id and entity_type='player_match' and entity_id=p_match_id::text and action='agency.pursuit_salary_review';end if;
 return result||jsonb_build_object('confirmed_command_id',receipt);
end $read$;

create function public.platform_server_record_pursuit_salary_review(p_tenant_id uuid,p_actor_user_id uuid,p_match_id uuid,p_command_id uuid,p_fingerprint text,p_decision text,p_reason text,p_expires_on date default null)
returns jsonb language plpgsql security definer set search_path='' as $write$
declare gate jsonb;v_match djm_os.player_matches%rowtype;existing platform.audit_events%rowtype;decision jsonb;today date:=(now() at time zone 'UTC')::date;reason text:=nullif(btrim(p_reason),'');
begin
 if private.user_is_tenant_admin(p_tenant_id,p_actor_user_id) is distinct from true then raise exception 'Agency administrator access required' using errcode='42501';end if;
 v_match:=private.lock_pursuit_salary_context(p_tenant_id,p_match_id);
 if p_command_id is null or p_fingerprint!~'^[0-9a-f]{32}$' or p_fingerprint is null or p_decision is null or p_decision not in('explore','hold','use_recorded_terms') or reason is null or length(reason)>2000 then raise exception 'Choose a decision and add a reason within 2,000 characters.' using errcode='22023';end if;
 decision:=jsonb_build_object('version',1,'fingerprint',p_fingerprint,'decision',p_decision,'reason',reason,'expires_on',p_expires_on,'expiry_basis','end_of_utc_date');
 select * into existing from platform.audit_events where id=p_command_id;
 if found then
  if existing.tenant_id is distinct from p_tenant_id or existing.actor_user_id is distinct from p_actor_user_id or existing.entity_type<>'player_match' or existing.entity_id<>p_match_id::text or existing.action<>'agency.pursuit_salary_review' or (existing.after_state-'context') is distinct from decision then raise exception 'This review command cannot be reused for different details.' using errcode='22023';end if;
  return public.platform_server_pursuit_salary_review(p_tenant_id,p_actor_user_id,p_match_id,p_command_id);
 end if;
 if p_decision='explore' and (p_expires_on is null or p_expires_on<today or p_expires_on>today+365) then raise exception 'Choose an exploration expiry within the next year.' using errcode='22023';end if;
 if p_decision<>'explore' and p_expires_on is not null then raise exception 'Only an exploration decision has an expiry.' using errcode='22023';end if;
 gate:=private.pursuit_salary_gate(p_tenant_id,p_match_id);
 if gate#>>'{comparison,fingerprint}' is distinct from p_fingerprint then raise exception 'The salary evidence changed. Load the current check and review your decision again.' using errcode='40001';end if;
 if p_decision='use_recorded_terms' and not(gate#>>'{comparison,state}' in('minimum_within_budget','target_within_budget') and gate#>>'{comparison,needs_source_confirmation}'='false') then raise exception 'Confirm compatible salary terms before using them without an exploration decision.' using errcode='22023';end if;
 insert into platform.audit_events(id,tenant_id,actor_user_id,actor_kind,action,entity_type,entity_id,after_state,metadata,occurred_at)
 values(p_command_id,p_tenant_id,p_actor_user_id,'user','agency.pursuit_salary_review','player_match',p_match_id::text,decision||jsonb_build_object('context',jsonb_build_object('player_id',v_match.player_id,'club_need_id',v_match.club_need_id,'club_id',(select organisation_id from djm_os.club_needs where id=v_match.club_need_id and tenant_id=p_tenant_id))),jsonb_build_object('source','pursuit_salary_review','scope','Exploration only; no salary agreement or career approval'),clock_timestamp());
 return public.platform_server_pursuit_salary_review(p_tenant_id,p_actor_user_id,p_match_id,p_command_id);
end $write$;
revoke all on function public.platform_server_pursuit_salary_review(uuid,uuid,uuid,uuid),public.platform_server_record_pursuit_salary_review(uuid,uuid,uuid,uuid,text,text,text,date) from public,anon,authenticated;
grant execute on function public.platform_server_pursuit_salary_review(uuid,uuid,uuid,uuid),public.platform_server_record_pursuit_salary_review(uuid,uuid,uuid,uuid,text,text,text,date) to service_role;

create function private.assert_pursuit_salary_progress(p_tenant_id uuid,p_match_id uuid)
returns void language plpgsql security invoker set search_path='' as $assert$
declare gate jsonb;
begin
 perform private.lock_pursuit_salary_context(p_tenant_id,p_match_id);
 gate:=private.pursuit_salary_gate(p_tenant_id,p_match_id);
 if gate->>'can_proceed' is distinct from 'true' then raise exception 'Review base-salary feasibility in this opportunity before preparing a new pitch or deal.' using errcode='22023';end if;
end $assert$;
revoke all on function private.assert_pursuit_salary_progress(uuid,uuid) from public,anon,authenticated,service_role;

-- Both private admin readers reuse this projection. Career and financial counts
-- stay separate; no held candidate becomes ready through a legacy high score.
create function private.enrich_need_salary_reviews(p_tenant_id uuid,p_control jsonb)
returns jsonb language plpgsql stable security invoker set search_path='' as $projection$
declare item jsonb;candidate jsonb;gate jsonb;items jsonb:='[]';candidates jsonb;progress_count integer;review_count integer;career_count integer;
begin
 for item in select value from jsonb_array_elements(coalesce(p_control->'items','[]'::jsonb)) loop
  candidates:='[]';progress_count:=0;review_count:=0;career_count:=0;
  for candidate in select value from jsonb_array_elements(coalesce(item#>'{candidate_coverage,candidates}','[]'::jsonb)) loop
   if exists(select 1 from public.players p where p.id=(candidate->>'player_id')::uuid and p.tenant_id=p_tenant_id and p.archived_at is null) then gate:=private.pursuit_salary_gate(p_tenant_id,(candidate->>'player_match_id')::uuid);
   else gate:=jsonb_build_object('version',1,'can_proceed',false,'state','hold_player_unavailable','message','Review this player record before progressing.','comparison',jsonb_build_object('version',1,'state','unavailable','message','Salary comparison is unavailable.'));end if;
   if candidate->>'career_gate_state' like 'open_%' then career_count:=career_count+1;if gate->>'can_proceed'='true' then progress_count:=progress_count+1;end if;end if;
   if gate->>'can_proceed' is distinct from 'true' then review_count:=review_count+1;end if;
   candidates:=candidates||jsonb_build_array(candidate||jsonb_build_object('salary_check',gate->'comparison','salary_gate',(gate-array['comparison','review'])||jsonb_build_object('review_active',gate#>'{review,active}','review_until',gate#>'{review,expires_on}')));
  end loop;
  select coalesce(jsonb_agg(c.value order by case when c.value->>'career_gate_state' like 'open_%' and c.value#>>'{salary_gate,can_proceed}'='true' then 0 when c.value->>'career_gate_state' like 'open_%' or c.value->>'career_gate_state' like 'review_%' then 1 else 2 end,c.ordinality),'[]'::jsonb) into candidates from jsonb_array_elements(candidates) with ordinality c;
  item:=jsonb_set(item,'{candidate_coverage}',coalesce(item->'candidate_coverage','{}'::jsonb)||jsonb_build_object('candidates',candidates,'progress_ready',progress_count,'salary_review_required',review_count));
  if career_count>0 and progress_count=0 and item->'next_action'<>'null'::jsonb then item:=item||jsonb_build_object('coverage_state','salary_review_required','next_action',jsonb_build_object('action_type','review_candidate_salary','instruction','Review candidate salary evidence before preparing new external activity.','requires_human_input',true));end if;
  items:=items||jsonb_build_array(item);
 end loop;
 return jsonb_set(p_control,'{items}',items);
end $projection$;
revoke all on function private.enrich_need_salary_reviews(uuid,jsonb) from public,anon,authenticated,service_role;

do $canonical$
declare spec jsonb;fn regprocedure;before_meta jsonb;after_meta jsonb;
begin
 for spec in select value from jsonb_array_elements($spec$[{"signature":"djm_os.refresh_need_matches(uuid)","hash":"5717ce0f9e0cbf44db1475f275a1f7c9","definition":"CREATE OR REPLACE FUNCTION djm_os.refresh_need_matches(p_need_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  n djm_os.club_needs%rowtype;\n  v_country text;\nbegin\n  select * into n from djm_os.club_needs where id = p_need_id;\n  if not found then return; end if;\n  select country into v_country from djm_os.organisations where id = n.organisation_id;\n\n  if n.status not in ('active', 'open', 'confirmed') then\n    delete from djm_os.player_matches where tenant_id=n.tenant_id and club_need_id = p_need_id and status = 'suggested';\n    return;\n  end if;\n\n  delete from djm_os.player_matches m using public.players p\n  where m.tenant_id=n.tenant_id and m.club_need_id = p_need_id and m.player_id = p.id and m.status = 'suggested'\n    and (p.archived_at is not null or coalesce(p.football_status,'active')='retired' or not (\n      djm_os.position_matches_player(n.position, p.primary_position, p.secondary_positions)\n      and (n.preferred_foot is null or p.preferred_foot is null or lower(p.preferred_foot) = lower(n.preferred_foot))\n      and (n.min_age is null or p.date_of_birth is null or date_part('year', age(current_date, p.date_of_birth)) >= n.min_age)\n      and (n.max_age is null or p.date_of_birth is null or date_part('year', age(current_date, p.date_of_birth)) <= n.max_age)\n      and (n.min_height_cm is null or p.height_cm is null or p.height_cm >= n.min_height_cm)\n    ));\n\n  with financial as materialized (\n    select p.id,private.player_need_salary_check(n.tenant_id,n.id,p.id) salary_check\n    from public.players p\n  where p.tenant_id=n.tenant_id and p.archived_at is null and coalesce(p.football_status,'active')<>'retired' and djm_os.position_matches_player(n.position, p.primary_position, p.secondary_positions)\n    and (n.preferred_foot is null or p.preferred_foot is null or lower(p.preferred_foot) = lower(n.preferred_foot))\n    and (n.min_age is null or p.date_of_birth is null or date_part('year', age(current_date, p.date_of_birth)) >= n.min_age)\n    and (n.max_age is null or p.date_of_birth is null or date_part('year', age(current_date, p.date_of_birth)) <= n.max_age)\n    and (n.min_height_cm is null or p.height_cm is null or p.height_cm >= n.min_height_cm)\n  )\n  insert into djm_os.player_matches(\n    tenant_id, club_need_id, player_id, overall_score, football_score, commercial_score,\n    registration_score, career_score, access_score, reasoning, status\n  )\n  select\n    n.tenant_id, n.id, p.id,\n    null::numeric,\n    s.football_score, s.commercial_score, s.registration_score, s.career_score, null::numeric,\n    jsonb_build_object(\n      'source', 'redream_recorded_match_checks_v1',\n      'model', 'Recorded checks; no aggregate fit prediction',\n      'coverage', s.coverage,\n      'components', jsonb_build_object(\n        'football_fit', s.football_score,\n        'commercial_fit', s.commercial_score,\n        'registration_fit', s.registration_score,\n        'career_fit', s.career_score,\n        'availability', s.availability_score\n      ),\n      'strengths', to_jsonb(array_remove(array[\n        'Primary or secondary position fits the requested role',\n        case when n.preferred_foot is not null and p.preferred_foot is not null then 'Preferred foot matches' end,\n        case when n.min_height_cm is not null and p.height_cm is not null then 'Minimum height is met' end,\n        case when p.date_of_birth is not null and (n.min_age is not null or n.max_age is not null) then 'Recorded age is within range' end\n      ], null)),\n      'concerns',to_jsonb(array_remove(array[case when fin.salary_check->>'needs_source_confirmation'='true' or fin.salary_check->>'state' not in('minimum_within_budget','target_within_budget') then 'Base-salary feasibility needs authorised review' end],null)),\n      'hard_blockers',to_jsonb(array_remove(array[case when fin.salary_check->>'hard_conflict'='true' then 'A confirmed financial incompatibility requires resolution or a justified exploration review' end],null)),\n      'missing_information', to_jsonb(array_remove(array[\n        case when p.date_of_birth is null and (n.min_age is not null or n.max_age is not null) then 'Player date of birth is not recorded' end,\n        case when p.preferred_foot is null and n.preferred_foot is not null then 'Player preferred foot is not recorded' end,\n        case when p.height_cm is null and n.min_height_cm is not null then 'Player height is not recorded' end,\n        case when fin.salary_check->>'needs_source_confirmation'='true' or fin.salary_check->>'state' not in('minimum_within_budget','target_within_budget') then 'Authorised current base-salary review' end,\n        case when nullif(trim(coalesce(n.passport_requirements, n.registration_notes, '')), '') is not null and cardinality(coalesce(f.passports_held, '{}')) = 0 then 'Passport evidence is not recorded' end\n      ], null)),\n      'sample', jsonb_build_object('career_minutes', coalesce(c.minutes, 0), 'career_appearances', coalesce(c.appearances, 0)),\n      'calculated_at', now()\n    ),\n    'suggested'\n  from public.players p\n  join financial fin on fin.id=p.id\n  left join djm_os.player_market_facts f on f.player_id = p.id\n  left join lateral (\n    select coalesce(sum(ce.minutes), 0)::numeric as minutes, coalesce(sum(ce.appearances), 0)::numeric as appearances\n    from public.career_entries ce where ce.player_id = p.id\n  ) c on true\n  cross join lateral (\n    select\n      least(100, 70\n        + case when n.preferred_foot is null then 6 when p.preferred_foot is null then 3 else 10 end\n        + case when n.min_age is null and n.max_age is null then 6 when p.date_of_birth is null then 3 else 8 end\n        + case when n.min_height_cm is null then 5 when p.height_cm is null then 2 else 7 end)::numeric as football_score,\n      null::numeric as commercial_score,\n      djm_os.registration_fit_score(coalesce(n.passport_requirements, n.registration_notes), f.work_rights, f.passports_held, v_country)::numeric as registration_score,\n      least(100, 45 + least(35, coalesce(c.minutes, 0) / 180) + least(20, coalesce(c.appearances, 0) / 5))::numeric as career_score,\n      case when lower(coalesce(p.football_status, '')) in ('free_agent', 'free agent', 'available') then 95 when lower(coalesce(p.football_status, '')) = 'active' then 82 when lower(coalesce(p.football_status, '')) = 'injured' then 30 else 60 end::numeric as availability_score,\n      round((\n        1\n        + case when n.preferred_foot is null or p.preferred_foot is not null then 1 else 0 end\n        + case when (n.min_age is null and n.max_age is null) or p.date_of_birth is not null then 1 else 0 end\n        + case when n.min_height_cm is null or p.height_cm is not null then 1 else 0 end\n        + case when fin.salary_check->>'needs_source_confirmation'='false' and fin.salary_check->>'state' in('minimum_within_budget','target_within_budget') then 1 else 0 end\n        + case when nullif(trim(coalesce(n.passport_requirements, n.registration_notes, '')), '') is null or cardinality(coalesce(f.passports_held, '{}')) > 0 then 1 else 0 end\n      )::numeric / 6 * 100)::int as coverage\n  ) s\n  where p.tenant_id=n.tenant_id and djm_os.position_matches_player(n.position, p.primary_position, p.secondary_positions)\n    and (n.preferred_foot is null or p.preferred_foot is null or lower(p.preferred_foot) = lower(n.preferred_foot))\n    and (n.min_age is null or p.date_of_birth is null or date_part('year', age(current_date, p.date_of_birth)) >= n.min_age)\n    and (n.max_age is null or p.date_of_birth is null or date_part('year', age(current_date, p.date_of_birth)) <= n.max_age)\n    and (n.min_height_cm is null or p.height_cm is null or p.height_cm >= n.min_height_cm)\n  on conflict (club_need_id, player_id) do update set\n    overall_score = excluded.overall_score,\n    football_score = excluded.football_score,\n    commercial_score = excluded.commercial_score,\n    registration_score = excluded.registration_score,\n    career_score = excluded.career_score,\n    reasoning = excluded.reasoning,\n    updated_at = now()\n  where djm_os.player_matches.status = 'suggested';\nend $function$\n"},{"signature":"public.platform_server_create_pitch_draft(uuid,uuid,uuid,jsonb)","hash":"1650aab999181a817633f6e057a70a4f","definition":"CREATE OR REPLACE FUNCTION public.platform_server_create_pitch_draft(p_tenant_id uuid, p_player_match_id uuid, p_actor_user_id uuid, p_input jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_role text;\n  v_match djm_os.player_matches%rowtype;\n  v_need djm_os.club_needs%rowtype;\n  v_gate jsonb;\n  v_share public.club_share_links%rowtype;\n  v_existing uuid;\n  v_deal_id uuid;\n  v_org_id uuid;\nbegin\n  select m.role into v_role from platform.tenant_memberships m join platform.tenants t on t.id=m.tenant_id and t.status='active'\n   where m.tenant_id=p_tenant_id and m.user_id=p_actor_user_id and m.status='active' and m.role in ('owner','admin','agent','operations') limit 1;\n  if v_role is null then raise exception 'agency_operator_access_required'; end if;\n\n  select * into v_match from djm_os.player_matches pm where pm.id=p_player_match_id and pm.tenant_id=p_tenant_id;\n  if not found then raise exception 'player_match_not_found_for_tenant'; end if;\n  select * into v_need from djm_os.club_needs n where n.id=v_match.club_need_id and n.tenant_id=p_tenant_id;\n  if not found then raise exception 'club_need_not_found_for_tenant'; end if;\n  v_org_id:=v_need.organisation_id;\n\n  v_gate:=public.platform_server_career_pursuit_gate(p_tenant_id,p_player_match_id);\n  if coalesce(v_gate->>'state','') not in ('open_aligned','open_approved_exception') then raise exception 'career_control_gate_not_open'; end if;\n  perform private.assert_pursuit_salary_progress(p_tenant_id,p_player_match_id);\n\n  select c.share_id into v_existing\n  from platform.club_pitch_contexts c join public.club_share_links s on s.id=c.share_id\n  where c.tenant_id=p_tenant_id and c.player_match_id=p_player_match_id and s.revoked_at is null\n  order by s.created_at desc limit 1;\n  if v_existing is not null then\n    return jsonb_build_object('created',false,'existing',true,'share_id',v_existing,'pitch',public.platform_server_pitch_execution_command(p_tenant_id,100));\n  end if;\n\n  if nullif(trim(p_input->>'deal_room_id'),'') is not null then\n    v_deal_id:=(p_input->>'deal_room_id')::uuid;\n    if not exists(select 1 from djm_os.deal_rooms d where d.id=v_deal_id and d.tenant_id=p_tenant_id and d.player_id=v_match.player_id and d.organisation_id=v_org_id) then\n      raise exception 'deal_room_does_not_match_pitch_context';\n    end if;\n  end if;\n\n  insert into public.club_share_links(player_id,label,active,expires_at,created_by,opportunity_id,organisation_id,pitch_message,pitch_status,selected_sections)\n  values(v_match.player_id,nullif(trim(p_input->>'label'),''),false,null,p_actor_user_id,v_deal_id,v_org_id,nullif(trim(p_input->>'pitch_message'),''),'draft',coalesce(p_input->'selected_sections','{}'::jsonb))\n  returning * into v_share;\n\n  insert into platform.club_pitch_contexts(share_id,tenant_id,player_match_id,club_need_id,created_by)\n  values(v_share.id,p_tenant_id,p_player_match_id,v_match.club_need_id,p_actor_user_id);\n\n  insert into platform.audit_events(tenant_id,actor_user_id,actor_kind,action,entity_type,entity_id,after_state,metadata)\n  values(p_tenant_id,p_actor_user_id,'user','club_pitch.draft_created','club_pitch',v_share.id::text,to_jsonb(v_share),jsonb_build_object('player_match_id',p_player_match_id,'club_need_id',v_match.club_need_id));\n\n  return jsonb_build_object(\n    'created',true,'existing',false,'share_id',v_share.id,'state','draft_private',\n    'truth_contract',jsonb_build_object('privacy','Draft pitch links are inactive and cannot be opened through the public club-share reader.','career','Draft creation requires an open human-owned career gate.','send','Creating a draft is not external outreach.')\n  );\nend;\n$function$\n"},{"signature":"public.platform_server_publish_pitch_link(uuid,uuid,uuid,timestamptz)","hash":"6ef83cabafd3ecab37e282af4f1e3aa1","definition":"CREATE OR REPLACE FUNCTION public.platform_server_publish_pitch_link(p_tenant_id uuid, p_share_id uuid, p_actor_user_id uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_role text;\n  v_ctx platform.club_pitch_contexts%rowtype;\n  v_share public.club_share_links%rowtype;\n  v_player public.players%rowtype;\n  v_profile public.player_public_profiles%rowtype;\n  v_gate jsonb;\n  v_expiry timestamptz:=coalesce(p_expires_at,now()+interval '30 days');\n  v_other integer:=0;\nbegin\n  select m.role into v_role from platform.tenant_memberships m join platform.tenants t on t.id=m.tenant_id and t.status='active'\n   where m.tenant_id=p_tenant_id and m.user_id=p_actor_user_id and m.status='active' and m.role in ('owner','admin','agent','operations') limit 1;\n  if v_role is null then raise exception 'agency_operator_access_required'; end if;\n  if v_expiry<=now() then raise exception 'pitch_expiry_must_be_future'; end if;\n\n  select * into v_ctx from platform.club_pitch_contexts c where c.share_id=p_share_id and c.tenant_id=p_tenant_id;\n  if not found then raise exception 'pitch_context_not_found_for_tenant'; end if;\n  select * into v_share from public.club_share_links s where s.id=p_share_id for update;\n  if not found or v_share.revoked_at is not null then raise exception 'pitch_share_not_available'; end if;\n  select * into v_player from public.players p where p.id=v_share.player_id and p.tenant_id=p_tenant_id;\n  if not found then raise exception 'player_not_found_for_tenant'; end if;\n  select * into v_profile from public.player_public_profiles pp where pp.player_id=v_player.id;\n\n  v_gate:=public.platform_server_career_pursuit_gate(p_tenant_id,v_ctx.player_match_id);\n  if coalesce(v_gate->>'state','') not in ('open_aligned','open_approved_exception') then raise exception 'career_control_gate_not_open'; end if;\n  perform private.assert_pursuit_salary_progress(p_tenant_id,v_ctx.player_match_id);\n  if v_player.verification_status<>'verified' or v_player.verified_at is null then raise exception 'player_not_verified_for_external_share'; end if;\n  if v_profile.player_id is null or not coalesce(v_profile.published,false) or v_profile.verified_at is null then raise exception 'club_profile_not_published_and_verified'; end if;\n\n  select count(*) into v_other from public.club_share_links s\n  join public.players p on p.id=s.player_id and p.tenant_id=p_tenant_id\n  where s.id<>p_share_id and s.player_id=v_share.player_id and s.organisation_id=v_share.organisation_id and s.active=true and s.revoked_at is null and (s.expires_at is null or s.expires_at>now());\n  if v_other>0 then raise exception 'another_active_pitch_exists_for_player_and_club'; end if;\n\n  update public.club_share_links\n  set active=true,expires_at=v_expiry,pitch_status=case when sent_at is null then 'ready' else pitch_status end\n  where id=p_share_id\n  returning * into v_share;\n\n  insert into platform.audit_events(tenant_id,actor_user_id,actor_kind,action,entity_type,entity_id,after_state,metadata)\n  values(p_tenant_id,p_actor_user_id,'user','club_pitch.published','club_pitch',p_share_id::text,to_jsonb(v_share),jsonb_build_object('player_match_id',v_ctx.player_match_id,'expires_at',v_expiry));\n\n  return jsonb_build_object('published',true,'share_id',p_share_id,'state','ready_not_confirmed_sent','expires_at',v_expiry,\n    'truth_contract',jsonb_build_object('public_link','The link is now externally accessible to anyone who possesses the unguessable share token until it is revoked or expires.','send','Publishing the link does not record that it was delivered to a club. A human must separately confirm sent.'));\nend;\n$function$\n"},{"signature":"public.platform_server_convert_pursuit_to_deal(uuid,uuid,uuid,jsonb)","hash":"64e62557366ffb4d76a55979859bdccb","definition":"CREATE OR REPLACE FUNCTION public.platform_server_convert_pursuit_to_deal(p_tenant_id uuid, p_player_match_id uuid, p_actor_user_id uuid, p_input jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_role text;\n  v_match djm_os.player_matches%rowtype;\n  v_need djm_os.club_needs%rowtype;\n  v_gate jsonb;\n  v_existing djm_os.deal_rooms%rowtype;\n  v_deal djm_os.deal_rooms%rowtype;\n  v_stage text:=nullif(trim(p_input->>'stage'),'');\n  v_probability int;\n  v_owner uuid:=coalesce(nullif(trim(p_input->>'owner_user_id'),'')::uuid,p_actor_user_id);\n  v_title text:=nullif(trim(p_input->>'title'),'');\n  v_expected numeric;\n  v_currency text:=upper(coalesce(nullif(trim(p_input->>'currency'),''),'EUR'));\n  v_blocker text:=nullif(trim(p_input->>'primary_blocker'),'');\n  v_decision text:=nullif(trim(p_input->>'next_decision'),'');\n  v_next_text text:=nullif(trim(p_input->>'next_action_text'),'');\n  v_next_at timestamptz;\nbegin\n  select m.role into v_role from platform.tenant_memberships m join platform.tenants t on t.id=m.tenant_id and t.status='active'\n  where m.tenant_id=p_tenant_id and m.user_id=p_actor_user_id and m.status='active' and m.role in ('owner','admin','agent','operations') limit 1;\n  if v_role is null then raise exception 'agency_operator_access_required'; end if;\n  if not exists(select 1 from platform.tenant_memberships m where m.tenant_id=p_tenant_id and m.user_id=v_owner and m.status='active') then raise exception 'deal_owner_not_active_tenant_member'; end if;\n\n  select * into v_match from djm_os.player_matches pm where pm.id=p_player_match_id and pm.tenant_id=p_tenant_id;\n  if not found then raise exception 'player_match_not_found_for_tenant'; end if;\n  select * into v_need from djm_os.club_needs n where n.id=v_match.club_need_id and n.tenant_id=p_tenant_id;\n  if not found then raise exception 'club_need_not_found_for_tenant'; end if;\n  v_gate:=public.platform_server_career_pursuit_gate(p_tenant_id,p_player_match_id);\n  if coalesce(v_gate->>'state','') not in ('open_aligned','open_approved_exception') then raise exception 'career_control_gate_not_open'; end if;\n  perform private.assert_pursuit_salary_progress(p_tenant_id,p_player_match_id);\n\n  select * into v_existing from djm_os.deal_rooms d\n  where d.tenant_id=p_tenant_id and d.player_id=v_match.player_id and d.organisation_id=v_need.organisation_id and d.status in ('active','paused')\n  order by d.created_at desc limit 1;\n  if found then return jsonb_build_object('created',false,'existing',true,'deal_room_id',v_existing.id,'deal',to_jsonb(v_existing),'truth_contract',jsonb_build_object('duplicates','An existing active/paused player-club deal was reused rather than duplicated.')); end if;\n\n  if v_stage not in ('qualifying','contacted','interest','negotiating','offer') then raise exception 'human_stage_required_for_new_deal'; end if;\n  if nullif(trim(p_input->>'probability'),'') is null then raise exception 'human_probability_required_for_new_deal'; end if;\n  v_probability:=(p_input->>'probability')::int;\n  if v_probability<0 or v_probability>100 then raise exception 'probability_must_be_0_to_100'; end if;\n  if nullif(trim(p_input->>'expected_commission'),'') is not null then\n    v_expected:=(p_input->>'expected_commission')::numeric;\n    if v_expected<0 then raise exception 'expected_commission_cannot_be_negative'; end if;\n  end if;\n  if nullif(trim(p_input->>'next_action_at'),'') is not null then v_next_at:=(p_input->>'next_action_at')::timestamptz; end if;\n  if v_title is null then v_title:=coalesce(nullif(trim(v_need.title),''),'Player pursuit')||' - '||coalesce((select o.name from djm_os.organisations o where o.id=v_need.organisation_id),'Club'); end if;\n\n  insert into djm_os.deal_rooms(\n    title,organisation_id,player_id,club_need_id,owner_user_id,stage,status,expected_commission,currency,probability,manual_probability,model_probability,probability_source,probability_basis,primary_blocker,next_decision,next_action_at,next_action_text,last_meaningful_at,source,tenant_id\n  ) values(\n    v_title,v_need.organisation_id,v_match.player_id,v_match.club_need_id,v_owner,v_stage,'active',v_expected,v_currency,v_probability,v_probability,null,'manual',jsonb_build_object('source','human_pursuit_conversion','player_match_id',p_player_match_id,'recorded_by',p_actor_user_id),v_blocker,v_decision,v_next_at,v_next_text,now(),'pursuit_conversion',p_tenant_id\n  ) returning * into v_deal;\n\n  insert into platform.audit_events(tenant_id,actor_user_id,actor_kind,action,entity_type,entity_id,after_state,metadata)\n  values(p_tenant_id,p_actor_user_id,'user','deal.created_from_pursuit','deal_room',v_deal.id::text,to_jsonb(v_deal),jsonb_build_object('player_match_id',p_player_match_id,'club_need_id',v_match.club_need_id));\n\n  return jsonb_build_object(\n    'created',true,'existing',false,'deal_room_id',v_deal.id,'deal',to_jsonb(v_deal),\n    'next_controls',jsonb_build_array(\n      jsonb_build_object('api_action','deal_origin_save','instruction','Confirm how this deal actually originated. DJM does not infer origin from the pursuit-conversion workflow.'),\n      jsonb_build_object('api_action','deal_war_room','instruction','Use the Deal War Room for execution control after creation.')\n    ),\n    'truth_contract',jsonb_build_object(\n      'probability','The recorded probability is human-supplied. Pursuit readiness is not converted into deal probability.',\n      'origin','Creating a deal from a pursuit does not establish the historical origin of the deal.',\n      'career','Conversion requires an open human-owned career gate.',\n      'external','Creating a Deal Room is internal tracking only and does not contact the club or player.'\n    )\n  );\nend;\n$function$\n"},{"signature":"public.platform_server_workspace_need_record(uuid,uuid,uuid)","hash":"7b7a00feb1a0365dd090b9fe87f01a10","definition":"CREATE OR REPLACE FUNCTION public.platform_server_workspace_need_record(p_tenant_id uuid, p_user_id uuid, p_need_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_result jsonb;\nbegin\n if p_tenant_id is null or p_user_id is null or not private.user_is_tenant_admin(p_tenant_id,p_user_id) then\n  raise exception 'tenant_admin_access_required' using errcode='42501';\n end if;\n with needs as (\n  select n.*,o.name club_name,o.country,o.city,o.league_name\n  from djm_os.club_needs n join djm_os.organisations o on o.id=n.organisation_id and o.tenant_id=n.tenant_id\n  where n.tenant_id=p_tenant_id and n.id=p_need_id and (to_jsonb(n)->>'archived_at') is null and (to_jsonb(o)->>'archived_at') is null\n  order by case n.need_type when 'confirmed' then 0 else 1 end,n.priority desc,n.expires_at nulls last,n.received_at desc\n\n), candidate_rows as materialized (\n  select pm.club_need_id,pm.id player_match_id,pm.player_id,pm.status match_status,\n    pm.overall_score,pm.football_score,pm.commercial_score,pm.registration_score,pm.career_score,pm.access_score,\n    pm.reasoning,pm.updated_at match_updated_at,\n    coalesce(nullif(trim(p.preferred_name),''),nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),'Player') player_name,\n    public.platform_server_career_pursuit_gate(p_tenant_id,pm.id) gate\n  from djm_os.player_matches pm join needs n on n.id=pm.club_need_id\n  join public.players p on p.id=pm.player_id and p.tenant_id=pm.tenant_id\n  where pm.tenant_id=p_tenant_id and p.archived_at is null and coalesce(p.football_status,'active')<>'retired' and pm.status in ('suggested','reviewing','shortlisted','pitched','active')\n), candidate_agg as (\n  select c.club_need_id,\n    count(*)::int recorded_candidates,\n    count(*) filter(where c.gate->>'state' like 'open_%')::int career_open,\n    count(*) filter(where c.gate->>'state' like 'review_%')::int human_review,\n    count(*) filter(where not (c.gate->>'state' like 'open_%') and not (c.gate->>'state' like 'review_%'))::int held,\n    coalesce(jsonb_agg(jsonb_build_object(\n      'player_match_id',c.player_match_id,\n      'player_id',c.player_id,\n      'player_name',c.player_name,\n      'match_status',c.match_status,\n      'overall_score',c.overall_score,\n      'football_score',c.football_score,\n      'commercial_score',c.commercial_score,\n      'registration_score',c.registration_score,\n      'career_score',c.career_score,\n      'access_score',c.access_score,\n      'reasoning',coalesce(c.reasoning,'{}'::jsonb),\n      'career_gate_state',c.gate->>'state',\n      'career_gate_reason',c.gate->>'reason'\n    ) order by\n      case when c.gate->>'state' like 'open_%' then 0 when c.gate->>'state' like 'review_%' then 1 else 2 end,\n      c.overall_score desc nulls last,\n      c.football_score desc nulls last,\n      case c.match_status when 'active' then 0 when 'pitched' then 1 when 'shortlisted' then 2 when 'reviewing' then 3 else 4 end,\n      c.match_updated_at desc,\n      c.player_name\n    ),'[]'::jsonb) candidates\n  from candidate_rows c group by c.club_need_id\n), direct_access as (\n  select distinct on (e.organisation_id) e.organisation_id,r.access_score,r.strength_score,r.trust_score,r.last_meaningful_at,p.full_name contact_name,e.role_title,r.team_member_id\n  from djm_os.relationships r join djm_os.employments e on e.tenant_id=r.tenant_id and e.person_id=r.person_id and e.is_current=true\n  join djm_os.people p on p.tenant_id=r.tenant_id and p.id=r.person_id\n  where r.tenant_id=p_tenant_id\n  order by e.organisation_id,r.access_score desc nulls last,r.strength_score desc nulls last,r.last_meaningful_at desc nulls last\n), base as (\n  select n.*,coalesce(c.recorded_candidates,0) recorded_candidates,coalesce(c.career_open,0) career_open,coalesce(c.human_review,0) human_review,coalesce(c.held,0) held,coalesce(c.candidates,'[]'::jsonb) candidates,\n    coalesce(d.access_score,0)::int direct_score,coalesce(d.strength_score,0)::int direct_strength,d.contact_name,d.role_title,d.team_member_id,\n    case when coalesce(d.access_score,0)<70 then public.platform_server_introduction_routes(p_tenant_id,n.organisation_id,1) else null end intro\n  from needs n left join candidate_agg c on c.club_need_id=n.id left join direct_access d on d.organisation_id=n.organisation_id\n), classified as (\n  select b.*,\n    coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0) intro_score,\n    case when b.direct_score>=70 then 'direct_route'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=70 and coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=b.direct_score+10 then 'warm_introduction'\n         when b.direct_score>0 then 'developing_direct_route'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>0 then 'developing_introduction'\n         else 'no_recorded_route' end access_mode,\n    case when b.recorded_candidates=0 then 'roster_gap'\n         when b.career_open=0 and b.human_review>0 then 'career_or_human_review_required'\n         when b.career_open=0 then 'career_blocked'\n         when b.direct_score>=70 then 'ready_direct'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=70 and coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=b.direct_score+10 then 'ready_via_introduction'\n         else 'access_gap' end coverage_state\n  from base b\n), ranked as (\n  select c.*,row_number() over(order by case c.need_type when 'confirmed' then 0 else 1 end,\n    case c.coverage_state when 'ready_direct' then 1 when 'ready_via_introduction' then 2 when 'access_gap' then 3 when 'career_or_human_review_required' then 4 when 'career_blocked' then 5 when 'roster_gap' then 6 else 9 end,\n    c.priority desc,c.expires_at nulls last,c.club_name,c.title) rn\n  from classified c\n), items as (\n  select r.*,case r.coverage_state\n    when 'roster_gap' then jsonb_build_object('action_type','scout_or_recruit_for_need','instruction','No recorded roster match exists for this active club need. Scout or recruit against the recorded profile rather than forcing an unsuitable player.','requires_human_input',true)\n    when 'career_or_human_review_required' then jsonb_build_object('action_type','resolve_pursuit_gate','instruction','A recorded candidate exists, but career-strategy or human review must be resolved before external escalation.','requires_human_input',true)\n    when 'career_blocked' then jsonb_build_object('action_type','resolve_player_strategy_control','instruction','Recorded candidates exist but none are open under the player career controls.','requires_human_input',true)\n    when 'ready_direct' then jsonb_build_object('action_type','open_deep_pursuit_review','instruction','A career-open candidate and strong direct route are recorded. Open the full pursuit review before any external pitch.','requires_human_input',true)\n    when 'ready_via_introduction' then jsonb_build_object('action_type','open_deep_pursuit_review','instruction','A career-open candidate exists and a warm introduction is the stronger route. Open the full pursuit review before using it.','requires_human_input',true)\n    else jsonb_build_object('action_type','build_club_access','instruction','A career-open candidate exists, but access is not yet strong enough. Build or source the route before spending the player relationship.','requires_human_input',true) end next_action\n  from ranked r\n)\nselect jsonb_build_object(\n  'available',true,'tenant_id',p_tenant_id,'generated_at',now(),\n  'summary',jsonb_build_object(\n    'active_needs',(select count(*) from items),\n    'ready_for_deep_pursuit_review',(select count(*) from items where coverage_state in ('ready_direct','ready_via_introduction')),\n    'roster_gaps',(select count(*) from items where coverage_state='roster_gap'),\n    'access_gaps',(select count(*) from items where coverage_state='access_gap'),\n    'career_or_human_review',(select count(*) from items where coverage_state in ('career_or_human_review_required','career_blocked'))\n  ),\n  'items',coalesce((select jsonb_agg(jsonb_build_object(\n    'command_rank',rn,'club_need_id',id,\n    'club',jsonb_build_object('organisation_id',organisation_id,'name',club_name,'country',country,'city',city,'league_name',league_name),\n    'need',jsonb_build_object('status',status,'title',title,'position',position,'secondary_position',secondary_position,'preferred_foot',preferred_foot,'min_age',min_age,'max_age',max_age,'min_height_cm',min_height_cm,'transfer_type',transfer_type,'transfer_budget',transfer_budget::text,'salary_budget',salary_budget::text,'currency',currency,'salary_period',salary_period,'salary_tax_basis',salary_tax_basis,'profile_notes',profile_notes,'raw_request',raw_request,'source_context',source_context,'source_status',source_status,'availability_notes',availability_notes,'contract_months',contract_months,'contract_guaranteed',contract_guaranteed,'option_months',option_months,'updated_at',updated_at,'level_requirements',level_requirements,'nationality_preferences',nationality_preferences,'passport_requirements',passport_requirements,'registration_notes',registration_notes,'foreign_player_notes',foreign_player_notes,'playing_style',playing_style,'source_person_id',source_person_id,'source_organisation_id',source_organisation_id,'received_on',case when received_date_confirmed then to_char(received_at,'YYYY-MM-DD') else null end,'source_person_name',(select p.full_name from djm_os.people p where p.id=source_person_id and p.tenant_id=p_tenant_id and p.archived_at is null),'source_organisation_name',(select o.name from djm_os.organisations o where o.id=source_organisation_id and o.tenant_id=p_tenant_id and o.archived_at is null),'priority',priority,'need_type',need_type,'confidence',confidence,'prediction_probability',prediction_probability,'confirmed_at',confirmed_at,'expires_at',expires_at,'received_at',received_at),\n    'coverage_state',coverage_state,\n    'candidate_coverage',jsonb_build_object('recorded_candidates',recorded_candidates,'career_open',career_open,'human_review',human_review,'held',held,'candidates',candidates),\n    'access',jsonb_build_object('mode',access_mode,'direct_score',direct_score,'direct_strength',direct_strength,'best_direct_contact',contact_name,'best_direct_role',role_title,'team_member_id',team_member_id,'introduction_score',intro_score,'best_introduction_route',intro->'best_route'),\n    'next_action',case when status='active' and (expires_at is null or expires_at>=now()) then next_action else null end\n  ) order by rn) from items),'[]'::jsonb),\n  'principle','Use a compact demand-control pass for portfolio allocation, preserving player-career gates and recorded access. Open the deep pursuit model before an external pitch.',\n  'truth_contract',jsonb_build_object(\n    'demand','Confirmed and predicted needs remain distinct. Predicted need is not treated as confirmed club instruction.',\n    'candidate','Recorded candidates are existing player-match records; no new football fit is invented by this fast control.',\n    'career','Every recorded candidate still passes through the human-owned career pursuit gate.',\n    'access','Direct access uses the best recorded direct relationship. Warm-introduction logic is checked only when direct access is below the operating threshold.',\n    'deep_review','Fast demand control does not calculate full pursuit readiness or transfer probability. A ready state means the prerequisites for deep human review are recorded.'\n  )\n) into v_result;\n v_result:=private.enrich_need_salary_reviews(p_tenant_id,v_result);\n return jsonb_build_object('available',jsonb_array_length(v_result->'items')>0,'item',v_result#>'{items,0}');\nend;\n$function$\n"},{"signature":"public.platform_server_demand_control_fast(uuid,integer,uuid)","hash":"6003e30014faa9d6ae12916a64a1dace","definition":"CREATE OR REPLACE FUNCTION public.platform_server_demand_control_fast(p_tenant_id uuid,p_limit integer,p_user_id uuid)\n RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''\nAS $function$\nbegin\n if p_tenant_id is null or p_user_id is null or private.user_is_tenant_admin(p_tenant_id,p_user_id) is distinct from true then raise exception 'Agency administrator access required' using errcode='42501';end if;\n return private.enrich_need_salary_reviews(p_tenant_id,public.platform_server_demand_control_fast(p_tenant_id,p_limit));\nend;\n$function$"}]$spec$::jsonb) loop
  fn:=to_regprocedure(spec->>'signature');
  if fn is null or not exists(select 1 from pg_proc where oid=fn and md5(prosrc)=spec->>'hash' and prosecdef and proconfig=array['search_path=""'])
   or has_function_privilege('authenticated',fn,'EXECUTE') or has_function_privilege('anon',fn,'EXECUTE') then raise exception 'Unreviewed financial workflow %',spec->>'signature';end if;
  select jsonb_build_object('oid',oid,'owner',proowner,'acl',proacl,'mode',prosecdef,'config',proconfig,'volatility',provolatile) into before_meta from pg_proc where oid=fn;
  execute spec->>'definition';
  select jsonb_build_object('oid',oid,'owner',proowner,'acl',proacl,'mode',prosecdef,'config',proconfig,'volatility',provolatile) into after_meta from pg_proc where oid=fn;
  if before_meta is distinct from after_meta then raise exception 'Financial workflow contract changed';end if;
 end loop;
end $canonical$;

-- The existing direct table policies also permit staff writes. Protect linked
-- pursuit publication/context creation there, while leaving general profile
-- shares, deactivation, recipient view counters and delivery history alone.
create function private.guard_pursuit_financial_write()
returns trigger language plpgsql security definer set search_path='' as $native$
declare match_id uuid;tenant uuid;gate jsonb;share_player uuid;share_club uuid;
begin
 if tg_table_schema='public' and tg_table_name='club_share_links' then
  if new.active is distinct from true then return new;end if;
  if tg_op='UPDATE' and row(new.player_id,new.organisation_id,new.active,new.expires_at,new.revoked_at,new.pitch_message,new.selected_sections,new.label) is not distinct from row(old.player_id,old.organisation_id,old.active,old.expires_at,old.revoked_at,old.pitch_message,old.selected_sections,old.label) then return new;end if;
  select c.player_match_id,c.tenant_id into match_id,tenant from platform.club_pitch_contexts c where c.share_id=new.id;
  share_player:=new.player_id;share_club:=new.organisation_id;
 elsif tg_table_schema='platform' and tg_table_name='club_pitch_contexts' then
  if not exists(select 1 from public.club_share_links s where s.id=new.share_id and s.active) then return new;end if;
  match_id:=new.player_match_id;tenant:=new.tenant_id;
  select s.player_id,s.organisation_id into share_player,share_club from public.club_share_links s where s.id=new.share_id;
 else
  if new.club_need_id is null or new.player_id is null then return new;end if;
  if tg_op='UPDATE' and row(new.tenant_id,new.player_id,new.club_need_id,new.organisation_id) is not distinct from row(old.tenant_id,old.player_id,old.club_need_id,old.organisation_id) then return new;end if;
  select m.id,m.tenant_id into match_id,tenant from djm_os.player_matches m join djm_os.club_needs n on n.id=m.club_need_id and n.tenant_id=m.tenant_id where m.tenant_id=new.tenant_id and m.player_id=new.player_id and m.club_need_id=new.club_need_id and n.organisation_id=new.organisation_id;
  if match_id is null then raise exception 'Create a player opportunity for this club request before linking a new deal.' using errcode='22023';end if;
 end if;
 if match_id is not null then
  if tg_table_name<>'deal_rooms' and not exists(select 1 from djm_os.player_matches m join djm_os.club_needs n on n.id=m.club_need_id and n.tenant_id=m.tenant_id where m.id=match_id and m.tenant_id=tenant and m.player_id=share_player and n.organisation_id=share_club) then raise exception 'The pitch player, club and request must match this opportunity.' using errcode='22023';end if;
  gate:=public.platform_server_career_pursuit_gate(tenant,match_id);
  if coalesce(gate->>'state','') not in('open_aligned','open_approved_exception') then raise exception 'Review the player career direction before new external activity.' using errcode='22023';end if;
  perform private.assert_pursuit_salary_progress(tenant,match_id);
 end if;
 return new;
end $native$;
revoke all on function private.guard_pursuit_financial_write() from public,anon,authenticated,service_role;
create trigger pursuit_salary_publication_guard before insert or update on public.club_share_links for each row execute function private.guard_pursuit_financial_write();
create trigger pursuit_salary_context_guard before insert or update on platform.club_pitch_contexts for each row execute function private.guard_pursuit_financial_write();
create trigger pursuit_salary_deal_guard before insert or update on djm_os.deal_rooms for each row execute function private.guard_pursuit_financial_write();

notify pgrst,'reload schema';
commit;
